// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(0));
        vm.assume(value > 0 && value <= 100 ether);

        uint256 depositsBefore = c.depositsCount();

        (bool success, ) = address(c).call{value: value}(data);
        require(success, "deposit failed");

        c.sendMoney(target, value, data);

        uint256 depositsAfter = c.depositsCount();

        assertTrue(depositsAfter == depositsBefore + 1, "depositsCount should increase by 1 per sendMoney call");
    }
}

